import {state,save,esc,dateKey} from '../../lib/store.js';
import {button,badge,empty} from '../pixel/primitives.js';
import {randomExcerpt} from '../../lib/training-text.js';
export const liveNews={data:null,loading:false,error:'',attempt:0,day:'',staticMode:false};
function hasLocalNewsBackend(){return !document.querySelector('meta[name="app-hosting"][content="static-pages"]')}
export async function loadNews(force=false){if(!hasLocalNewsBackend()){liveNews.loading=false;liveNews.attempt=Date.now();liveNews.day=dateKey();liveNews.data=null;liveNews.staticMode=true;liveNews.error='STATIC HOST · LIVE RSS REQUIRES THE LOCAL SERVER';return true}if(liveNews.loading||!force&&liveNews.day===dateKey()&&Date.now()-liveNews.attempt<45*60000)return false;liveNews.staticMode=false;liveNews.loading=true;liveNews.attempt=Date.now();liveNews.day=dateKey();liveNews.error='';try{const response=await fetch('/api/news'+(force?'?refresh=1':''),{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('新闻服务暂时不可用');liveNews.data=await response.json()}catch(e){liveNews.error=e.message}finally{liveNews.loading=false}return true}
export function selectedArticle(){return state.selectedNews?.date===dateKey()?state.selectedNews.article:null}
export function chooseArticle(id){const article=liveNews.data?.articles.find(a=>a.id===id);if(!article)return;state.selectedNews={date:dateKey(),article:{...article,articleId:article.id}};ensureExcerpt(true);save()}
export function ensureExcerpt(force=false){const a=selectedArticle();if(!a)return null;if(force||state.newsExercise?.date!==dateKey()||state.newsExercise?.articleId!==a.id){const next=randomExcerpt(a.availableText,state.newsExercise?.excerpt);if(next.text===state.newsExercise?.excerpt&&state.newsExercise?.articleId===a.id&&state.newsExercise?.date===dateKey())return state.newsExercise;state.newsExercise={date:dateKey(),articleId:a.id,excerpt:next.text,count:next.count,draftKey:'news-'+a.id+'-'+Date.now()};save()}return state.newsExercise}
export function newsView(ui){const data=liveNews.data;let articles=(data?.articles||[]).filter(a=>!ui.newsCategory||a.category===ui.newsCategory);const today=articles.filter(a=>dateKey(a.publishedAt)===dateKey());let windowLabel='TODAY';if(today.length)articles=today;else{const recent=articles.filter(a=>Date.now()-Date.parse(a.publishedAt)<=48*3600000);articles=recent.length?recent:articles;windowLabel=recent.length?'PAST 48 HOURS':'PAST 72 HOURS'}const a=selectedArticle(),emptyMessage=liveNews.staticMode?'STATIC PREVIEW · 实时 RSS 需要在 127.0.0.1:8765 运行本地服务器。':liveNews.loading||!liveNews.attempt?'正在读取官方 RSS…':'此分类最近 72 小时暂无可用新闻。可以切换分类或稍后刷新。';return `<div class="row wrap mb"><div>${badge('OFFICIAL RSS / FREE','cyan')} <span class="micro muted">45 MIN CACHE · ${windowLabel}</span></div>${button(liveNews.loading?'LOADING…':'REFRESH NEWS','news-refresh',liveNews.loading||liveNews.staticMode?'disabled':'')}</div><div class="actions mb">${['','Política','Economia','Sociedade'].map(c=>button(c||'ALL','news-filter',`data-value="${c}"`,ui.newsCategory===c?'primary':'')).join('')}</div><div class="news-sources">${(data?.sources||[]).map(s=>`<span class="micro ${s.status==='ok'?'muted':'warning'}">${esc(s.label)} · ${s.status==='ok'?'ONLINE':s.status==='stale'?'CACHED / SOURCE UNAVAILABLE':'SOURCE TEMPORARILY UNAVAILABLE'} ${esc(s.error)}</span>`).join('')}</div>${liveNews.error?`<div class="notice">${esc(liveNews.error)}${data?' · 保留上次读取的真实新闻，日期不变。':''}</div>`:''}${a?`<div class="notice">TODAY'S SELECTED ARTICLE · ${esc(a.title)}</div>`:''}<p class="small muted">只展示媒体 RSS 提供的文本。READ 打开原站；训练不抓取付费全文。更新时间：${data?new Date(data.checkedAt).toLocaleString():'等待连接'}。</p><div class="live-news-grid">${articles.map(n=>`<article class="panel news-item"><div class="row wrap">${badge(n.category,'magenta')}<span class="micro">${esc(n.source)}</span></div><h3 lang="pt">${esc(n.title)}</h3><p class="micro muted">${dateKey(n.publishedAt)===dateKey()?'Today · ':dateKey(n.publishedAt)===dateKey(new Date().setDate(new Date().getDate()-1))?'Yesterday · ':''}${esc(new Date(n.publishedAt).toLocaleString())}</p><p lang="pt">${esc(n.description||'此条 RSS 未提供摘要。')}</p><div class="actions"><a class="button" href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">READ ↗</a>${button(a?.id===n.id?'SELECTED / TRAIN':'USE FOR TRAINING','news-select',`data-id="${esc(n.id)}" ${!n.availableText?'disabled title="RSS 未提供可训练文本"':''}`,'primary')}</div></article>`).join('')||empty(emptyMessage)}</div>`}
